package io.mutastic.worker;

import java.util.Collections;
import java.util.IdentityHashMap;

/// Whether a failure is the JVM refusing a class defined twice in one loader (`LinkageError: …
/// attempted duplicate class definition`), anywhere in its causes or what they suppressed.
///
/// That's the worker's doing, never the mutant's: a library that keeps what it generated by the
/// thread's context class loader, as Spring's CGLIB proxies are kept, misses it in each run's new
/// test loader and defines the class again where its target lives, in the production loader that
/// outlasts the run. The build runs every test under one loader, so it never sees this, and a test
/// that fails this way has judged nothing.
final class DuplicateClass {
  private static final String SAID = "duplicate class definition";

  private DuplicateClass() {}

  /// Each cause is visited once, so a chain that loops back on itself still ends.
  static boolean in(Throwable thrown) {
    var visited = Collections.newSetFromMap(new IdentityHashMap<Throwable, Boolean>());
    for (Throwable cause = thrown; cause != null && visited.add(cause); cause = cause.getCause()) {
      if (isOne(cause)) {
        return true;
      }
      for (Throwable suppressed : cause.getSuppressed()) {
        if (isOne(suppressed)) {
          return true;
        }
      }
    }
    return false;
  }

  private static boolean isOne(Throwable thrown) {
    return thrown instanceof LinkageError
        && thrown.getMessage() != null
        && thrown.getMessage().contains(SAID);
  }
}
